const s = $('Settings Loader').first().json;
const CONFIG = { DEFAULT_TIMEZONE: s.timezone, WINDOW_DAYS: s.roi_report_window_days };
const items = $input.all();
const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const windowStart = now.minus({ days: CONFIG.WINDOW_DAYS });
let newLeads = 0;
for (const item of items) {
  const lead = item.json;
  const createdRaw = (lead['Date Created'] || '').toString().trim();
  if (!createdRaw) continue;
  const created = DateTime.fromISO(createdRaw, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!created.isValid) continue;
  if (created >= windowStart && created <= now) newLeads++;
}
return [{ json: { metricGroup: 'leads', newLeads } }];

const s = $('Settings Loader').first().json;
const CONFIG = { DEFAULT_TIMEZONE: s.timezone, WINDOW_DAYS: s.roi_report_window_days };
const items = $input.all();
const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const windowStart = now.minus({ days: CONFIG.WINDOW_DAYS });
let appointmentsKept = 0;
for (const item of items) {
  const appt = item.json;
  const status = (appt['Status'] || '').toString().trim();
  const dateStr = (appt['Appt Date'] || '').toString().trim();
  const dateMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (dateMatch && status !== 'Cancelled') {
    const apptDate = DateTime.fromObject({ year: parseInt(dateMatch[1], 10), month: parseInt(dateMatch[2], 10), day: parseInt(dateMatch[3], 10) }, { zone: CONFIG.DEFAULT_TIMEZONE });
    if (apptDate >= windowStart && apptDate <= now) appointmentsKept++;
  }
}
return [{ json: { metricGroup: 'appointments', appointmentsKept: appointmentsKept } }];

const s = $('Settings Loader').first().json;
const CONFIG = { DEFAULT_TIMEZONE: s.timezone, WINDOW_DAYS: s.roi_report_window_days };
const items = $input.all();
const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const windowStart = now.minus({ days: CONFIG.WINDOW_DAYS });
let missedCallsRecovered = 0;
let appointmentsBooked = 0;
for (const item of items) {
  const log = item.json;
  const channel = (log['Channel'] || '').toString().trim();
  const summary = (log['Message Summary'] || '').toString().trim();
  const whenRaw = (log['Date / Time'] || '').toString().trim();
  if (!whenRaw) continue;
  const when = DateTime.fromISO(whenRaw, { zone: CONFIG.DEFAULT_TIMEZONE });
  if (!when.isValid) continue;
  if (when < windowStart || when > now) continue;
  if (channel === 'Phone' && /missed call/i.test(summary)) missedCallsRecovered++;
  if (/^Appointment confirmation SMS sent/i.test(summary)) appointmentsBooked++;
}
return [{ json: { metricGroup: 'recoveries', missedCallsRecovered: missedCallsRecovered, appointmentsBooked: appointmentsBooked } }];

const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  CLIENT_EMAIL: s.owner_email,
  CLIENT_PHONE: s.owner_phone_e164,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  EMAIL_ALERTS_ENABLED: s.email_alerts_enabled,
  SMS_ALERTS_ENABLED: s.sms_reports_enabled,
  DEFAULT_TIMEZONE: s.timezone,
  WINDOW_DAYS: s.roi_report_window_days
};

const items = $input.all();
const byGroup = {};
for (const item of items) {
  const g = item.json && item.json.metricGroup;
  if (g) byGroup[g] = item.json;
}
const leads = byGroup.leads || { newLeads: 0 };
const appts = byGroup.appointments || { appointmentsKept: 0 };
const recoveries = byGroup.recoveries || { missedCallsRecovered: 0, appointmentsBooked: 0 };

const dateLabel = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toFormat('LLLL d, yyyy');

let closing = 'That is ' + recoveries.appointmentsBooked + ' potential job(s) this system helped put on your calendar';
if (recoveries.missedCallsRecovered > 0) {
  closing += ', including ' + recoveries.missedCallsRecovered + ' that started as a missed call your business would not have otherwise followed up on.';
} else {
  closing += '.';
}

const smsLines = [];
smsLines.push('Your ' + CONFIG.COMPANY_NAME + ' System -- Last ' + CONFIG.WINDOW_DAYS + ' Days');
smsLines.push('');
smsLines.push('New leads captured: ' + leads.newLeads);
smsLines.push('Missed calls recovered with an instant text-back: ' + recoveries.missedCallsRecovered);
smsLines.push('Appointments booked: ' + recoveries.appointmentsBooked);
smsLines.push('Appointments kept (not cancelled): ' + appts.appointmentsKept);
smsLines.push('');
smsLines.push(closing);
smsLines.push('');
smsLines.push('Want the math behind any of these numbers, or to talk about what is next? Just reply -- happy to walk through it.');
const smsMessage = smsLines.join('\n');

const emailSubject = 'Your ' + CONFIG.COMPANY_NAME + ' Results — Last ' + CONFIG.WINDOW_DAYS + ' Days';

const metricRows = [
  ['New Leads Captured', leads.newLeads],
  ['Missed Calls Recovered', recoveries.missedCallsRecovered],
  ['Appointments Booked', recoveries.appointmentsBooked],
  ['Appointments Kept', appts.appointmentsKept]
].map(([label, value]) =>
  '<tr><td style="padding:6px 12px 6px 0;font-weight:bold;color:#374151;">' + label + '</td><td style="padding:6px 0;color:#111827;">' + value + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;">' +
  '<h2 style="color:#111827;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">Your Results, Last ' + CONFIG.WINDOW_DAYS + ' Days</h2>' +
  '<p style="color:#6b7280;margin-top:0;">' + dateLabel + '</p>' +
  '<table style="width:100%;border-collapse:collapse;margin-top:12px;">' + metricRows + '</table>' +
  '<p style="margin-top:20px;color:#374151;">' + closing + '</p>' +
  '<p style="margin-top:16px;color:#374151;">Want the math behind any of these numbers, or to talk about what is next? Just reply — happy to walk through it.</p>' +
  '</div>';

return [{ json: {
  emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
  smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
  clientEmail: CONFIG.CLIENT_EMAIL,
  clientPhone: CONFIG.CLIENT_PHONE,
  twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
  emailSubject,
  emailHtml,
  smsMessage,
  reportWindowDays: CONFIG.WINDOW_DAYS,
  newLeads: leads.newLeads,
  missedCallsRecovered: recoveries.missedCallsRecovered,
  appointmentsBooked: recoveries.appointmentsBooked,
  appointmentsKept: appts.appointmentsKept
} }];
